-- CreateEnum
CREATE TYPE "request_status" AS ENUM (
    'new',
    'contacted',
    'quote_sent',
    'confirmed',
    'completed',
    'cancelled'
);

-- Human-friendly request numbers are generated by PostgreSQL so concurrent
-- submissions cannot receive the same code.
CREATE SEQUENCE "request_code_seq"
    AS BIGINT
    START WITH 1042
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

