    CONSTRAINT "order_requests_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "order_requests_request_code_format" CHECK ("request_code" ~ '^REQ-[0-9]+$'),
    CONSTRAINT "order_requests_hospital_name_not_blank" CHECK (btrim("hospital_name") <> ''),
    CONSTRAINT "order_requests_contact_person_not_blank" CHECK (btrim("contact_person") <> ''),
    CONSTRAINT "order_requests_contact_phone_not_blank" CHECK (btrim("contact_phone") <> '')
);

