-- AddForeignKey
ALTER TABLE "products"
    ADD CONSTRAINT "products_category_id_fkey"
    FOREIGN KEY ("category_id") REFERENCES "product_categories"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "product_images"
    ADD CONSTRAINT "product_images_product_id_fkey"
    FOREIGN KEY ("product_id") REFERENCES "products"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "order_request_items"
    ADD CONSTRAINT "order_request_items_request_id_fkey"
    FOREIGN KEY ("request_id") REFERENCES "order_requests"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "order_request_items"
    ADD CONSTRAINT "order_request_items_product_id_fkey"
    FOREIGN KEY ("product_id") REFERENCES "products"("id")
    ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "request_status_history"
    ADD CONSTRAINT "request_status_history_request_id_fkey"
    FOREIGN KEY ("request_id") REFERENCES "order_requests"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

-- Supabase exposes the public schema through its Data API. RLS is enabled on
-- every domain table and no broad anon/authenticated policies are granted;
-- catalog reads, customer submissions, and staff operations go through Nuxt APIs.
ALTER TABLE "product_categories" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "products" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "product_images" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "order_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "order_request_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "request_status_history" ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE "order_requests" IS 'Customer equipment requests submitted for telephone confirmation.';
COMMENT ON COLUMN "order_requests"."request_code" IS 'Human-friendly code customers quote during the confirmation call.';
COMMENT ON COLUMN "order_request_items"."product_sku" IS 'SKU snapshot retained even if the linked product later changes or is deleted.';
COMMENT ON COLUMN "order_request_items"."product_name" IS 'Product-name snapshot retained even if the linked product later changes or is deleted.';
